/**
 * Ban comments. Code says what it does through its names and types; a
 * suppression carries its reason after ` -- `; history belongs in the commit
 * message and a rule in a lint rule or a type. Doc comments (`/**` blocks on the
 * lines above a declaration or member) stay, since editors show them to
 * callers, and so do comments that instruct a tool (suppressions, `@ts-*`,
 * `@effect-diagnostics`, triple-slash references, bundler annotations and
 * magic comments, JSX pragmas, formatter and coverage ignores), and a
 * generated file's header, which tools read to leave the file alone.
 */
import type { Comment } from "@oxlint/plugins";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";

import { AST, Diagnostic, Rule, RuleContext, Visitor } from "../vendor/effect-oxlint/index.js";
import { isToolDirective } from "./_comment-directives.js";

const isBlank = (text: string) => /^[\t ]*$/u.test(text);

type Range = readonly [number, number];

/**
 * A `/** *\/` block that stands alone on its lines with code right below it,
 * which editors attach to that code as its documentation.
 */
const isDocComment = (text: string, comment: Comment): boolean => {
  if (comment.type !== "Block" || !comment.value.startsWith("*")) return false;
  const [start, end] = comment.range;
  const lineStart = text.lastIndexOf("\n", start - 1) + 1;
  const lineBreak = text.indexOf("\n", end);
  if (!isBlank(text.slice(lineStart, start)) || lineBreak === -1) return false;
  if (!isBlank(text.slice(end, lineBreak))) return false;
  return /^\s*[^\s)\]},;/]/u.test(text.slice(lineBreak));
};

const generatedMark =
  /@generated\b|\bgenerated by\b|\bauto-?generated\b|\bdo not edit\b|\bedits will be (?:replaced|overwritten|lost)\b/iu;

/** The file's first comment, before any code, marking the file as a generator's output. */
const isGeneratedHeader = (text: string, comment: Comment): boolean =>
  /^(?:#![^\n]*\n)?\s*$/u.test(text.slice(0, comment.range[0])) &&
  generatedMark.test(comment.value);

const encloses = (outer: Range, inner: Range) => outer[0] < inner[0] && inner[1] < outer[1];

/**
 * The span a comment occupies: the braces around it when it is the only
 * content of a JSX expression container, else the comment itself.
 */
const occupiedSpan = (comment: Comment, emptyJsxContainers: ReadonlyArray<Range>): Range =>
  Option.getOrElse(
    Option.fromNullishOr(
      emptyJsxContainers.find((container) => encloses(container, comment.range)),
    ),
    () => comment.range,
  );

/**
 * The range to delete with a span: its whole line when it stands alone,
 * the space before it when it trails code, and one space beside it when it
 * sits between tokens.
 */
const removalRange = (text: string, [start, end]: Range): [number, number] => {
  const lineStart = text.lastIndexOf("\n", start - 1) + 1;
  const newline = text.indexOf("\n", end);
  let lineEnd = text.length;
  let nextLine = text.length;
  if (newline !== -1) {
    lineEnd = newline;
    nextLine = newline + 1;
  }
  const before = text.slice(lineStart, start);
  const after = text.slice(end, lineEnd);
  if (isBlank(before) && isBlank(after)) return [lineStart, nextLine];
  if (isBlank(after)) return [lineStart + before.trimEnd().length, lineEnd];
  if (text[end] === " ") return [start, end + 1];
  if (text[start - 1] === " ") return [start - 1, end];
  return [start, end];
};

export const noComments = Rule.define({
  name: "no-comments",
  meta: Rule.meta({
    type: "suggestion",
    fixable: "code",
    description:
      "Ban comments other than doc comments and tool directives: name the code instead, and put reasons in suppressions, history in commits, and rules in lint rules or types.",
    messages: {
      comment:
        "Comments are not allowed. Say it in a name or a type, give a suppression its reason after ` -- `, put history in the commit message, and turn a rule into a lint rule.",
    },
  }),
  create: function* () {
    const ctx = yield* RuleContext;
    return yield* Visitor.accumulate(
      "JSXExpressionContainer",
      (node) =>
        Option.flatMap(AST.narrow(node, "JSXExpressionContainer"), (container) =>
          Option.as(AST.narrow(container.expression, "JSXEmptyExpression"), container.range),
        ),
      (emptyJsxContainers) =>
        Effect.forEach(
          ctx.sourceCode
            .getAllComments()
            .filter(
              (comment) =>
                comment.type !== "Shebang" &&
                !isToolDirective(comment.value) &&
                !isDocComment(ctx.sourceCode.text, comment) &&
                !isGeneratedHeader(ctx.sourceCode.text, comment),
            ),
          (comment) =>
            ctx.report(
              Diagnostic.withFix(
                Diagnostic.fromId({ node: comment, messageId: "comment" }),
                (fixer) =>
                  fixer.removeRange(
                    removalRange(ctx.sourceCode.text, occupiedSpan(comment, emptyJsxContainers)),
                  ),
              ),
            ),
          { discard: true },
        ),
    );
  },
});
